import{_ as n,a0 as o,w as l,s as p,ao as u,I as r,x as t,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"关于哈希（散列）函数你应该知道的东西 | LCTT x X-CMD","titleTemplate":false,"description":"关于哈希（散列）函数你应该知道的东西 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"关于哈希（散列）函数你应该知道的东西 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"关于哈希（散列）函数你应该知道的东西 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200707 What you need to know about hash functions","title":"关于哈希（散列）函数你应该知道的东西","tag":"202007","desc":""},"relativePath":"202007/20200707 What you need to know about hash functions.md","filePath":"[post].md"}'),d={name:"202007/20200707 What you need to know about hash functions.md"};function b(h,e,f,m,y,g){const a=o("Link");return l(),p("div",null,[e[15]||(e[15]=u(`<h1 id="关于哈希-散列-函数你应该知道的东西" tabindex="-1">关于哈希（散列）函数你应该知道的东西 <a class="header-anchor" href="#关于哈希-散列-函数你应该知道的东西" aria-label="Permalink to “关于哈希（散列）函数你应该知道的东西”">​</a></h1><blockquote><p>从输出的哈希值反推回输入，这从计算的角度是不可行的。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/12/145709d3ne3vee330oh3lv.jpg" alt=""></p><p>无论安全从业人员用计算机做什么，有一种工具对他们每个人都很有用：加密<ruby>哈希（散列）<rt>hash</rt></ruby>函数。这听起来很神秘、很专业，甚至可能有点乏味，但是， 在这里，关于什么是哈希函数以及它们为什么对你很重要，我会作出一个简洁的解释。</p><p>加密哈希函数，比如 SHA-256 或者 MD5，接受一组二进制数据（通常是字节）作为输入，并且对每个可能的输入集给出一个<ruby>希望唯一<rt>hopefully unique</rt></ruby>的输出。对于任意模式的输入，给定的哈希函数的输出（“哈希值”）的长度都是一样的（对于 SHA-256，是 32 字节或者 256 比特，这从名字中就能看出来）。最重要的是：从输出的哈希值反推回输入，这从计算的角度是<ruby>不可行的<rt>implausible</rt></ruby>（密码学家讨厌 “<ruby>不可能<rt>impossible</rt></ruby>” 这个词）。这就是为什么它们有时候被称作<ruby>单向哈希函数<rt>one-way hash function</rt></ruby>。</p><p>但是哈希函数是用来做什么的呢？为什么“唯一”的属性如此重要？</p><h3 id="唯一的输出" tabindex="-1">唯一的输出 <a class="header-anchor" href="#唯一的输出" aria-label="Permalink to “唯一的输出”">​</a></h3><p>在描述哈希函数的输出时，“<ruby>希望唯一<rt>hopefully unique</rt></ruby>”这个短语是至关重要的，因为哈希函数就是用来呈现完全唯一的输出。比如，哈希函数可以用于验证 <em>你</em> 下载的文件副本的每一个字节是否和 <em>我</em> 下载的文件一样。你下载一个 Linux 的 ISO 文件或者从 Linux 的仓库中下载软件时，你会看到使用这个验证过程。没有了唯一性，这个技术就没用了，至少就通常的目的而言是这样的。</p><p>如果两个不同的输入产生了相同的输出，那么这样的哈希过程就称作“<ruby>碰撞<rt>collision</rt></ruby>”。事实上，MD5 算法已经被弃用，因为虽然可能性微乎其微，但它现在可以用市面上的硬件和软件系统找到碰撞。</p><p>另外一个重要的特性是，消息中的一个微小变化，甚至只是改变一个比特位，都可能会在输出中产生一个明显的变化（这就是“<ruby>雪崩效应<rt>avalanche effect</rt></ruby>”）。</p><h3 id="验证二进制数据" tabindex="-1">验证二进制数据 <a class="header-anchor" href="#验证二进制数据" aria-label="Permalink to “验证二进制数据”">​</a></h3><p>哈希函数的典型用途是当有人给你一段二进制数据，确保这些数据是你所期望的。无论是文本、可执行文件、视频、图像或者一个完整的数据库数据，在计算世界中，所有的数据都可以用二进制的形式进行描述，所以至少可以这么说，哈希是广泛适用的。直接比较二进制数据是非常缓慢的且计算量巨大，但是哈希函数在设计上非常快。给定两个大小为几 M 或者几 G 的文件，你可以事先生成它们的哈希值，然后在需要的时候再进行比较。</p><p>通常，对哈希值进行签名比对大型数据集本身进行签名更容易。这个特性太重要了，以至于密码学中对哈希值最常见的应用就是生成“数字”签名。</p><p>由于生成数据的哈希值很容易，所以通常不需要有两套数据。假设你想在你的电脑上运行一个可执行文件。但是在你运行之前，你需要检查这个文件就是你要的文件，没有被黑客篡改。你可以方便快捷的对文件生成哈希值，只要你有一个这个哈希值的副本，你就可以相当肯定这就是你想要的文件。</p><p>下面是一个简单的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shasum -a256 ~/bin/fop</span></span>
<span class="line"><span>87227baf4e1e78f6499e4905e8640c1f36720ae5f2bd167de325fd0d4ebc791c  /home/bob/bin/fop</span></span></code></pre></div><p>如果我知道 <code>fop</code> 这个可执行文件的 SHA-256 校验和，这是由供应商（这个例子中是 Apache 基金会）提供的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>87227baf4e1e78f6499e4905e8640c1f36720ae5f2bd167de325fd0d4ebc791c</span></span></code></pre></div><p>然后我就可以确信，我驱动器上的这个可执行文件和 Apache 基金会网站上发布的文件是一模一样的。这就是哈希函数难以发生碰撞（或者至少是 <em>很难通过计算得到碰撞</em>）这个性质的重要之处。如果黑客能将真实文件用哈希值相同的文件轻易的进行替换，那么这个验证过程就毫无用处。</p><p>事实上，这些性质还有更技术性的名称，我上面所描述的将三个重要的属性混在了一起。更准确地说，这些技术名称是：</p><ol><li><ruby>抗原像性<rt>pre-image resistance</rt></ruby>：给定一个哈希值，即使知道用了什么哈希函数，也很难得到用于创建它的消息。</li><li><ruby>抗次原像性<rt>second pre-image resistance</rt></ruby>：给定一个消息，很难找到另一个消息，使得这个消息可以产生相同的哈希值。</li><li><ruby>抗碰撞性<rt>collision resistance</rt></ruby>：很难得到任意两个可以产生相同哈希值的消息。</li></ol><p><em>抗碰撞性</em> 和 <em>抗次原像性</em> 也许听上去是同样的性质，但它们具有细微而显著的不同。<em>抗次原像性</em> 说的是如果 <em>已经</em> 有了一个消息，你也很难得到另一个与之哈希值相匹配的消息。<em>抗碰撞性</em> 使你很难找到两个可以生成相同哈希值的消息，并且要在哈希函数中实现这一性质则更加困难。</p><p>让我回到黑客试图替换文件（可以通过哈希值进行校验）的场景。现在，要在“外面”使用加密哈希算法（除了使用那些在现实世界中由独角兽公司开发的完全无 Bug 且安全的实现之外），还有一些重要且困难的附加条件需要满足。认真的读者可能已经想到了其中一些，特别需要指出的是：</p><ol><li>你必须确保自己所拥有的哈希值副本也没有被篡改。</li><li>你必须确保执行哈希算法的实体能够正确执行并报告了结果。</li><li>你必须确保对比两个哈希值的实体确实报告了这个对比的正确结果。</li></ol><p>确保你能满足这些条件绝对不是一件容易的事。这就是<ruby>可信平台模块<rt>Trusted Platform Modules</rt></ruby>（TPM）成为许多计算系统一部分的原因之一。它们扮演着信任的硬件基础，可以为验证重要二进制数据真实性的加密工具提供保证。TPM 对于现实中的系统来说是有用且重要的工具，我也打算将来写一篇关于 TPM 的文章。</p><hr>`,26)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),s(a,{href:"https://opensource.com/article/20/7/hash-functions"},{default:i(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/20/7/hash-functions",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("作者：",-1)),s(a,{href:"https://opensource.com/users/mikecamel"},{default:i(()=>[...e[2]||(e[2]=[t("Mike Bursell",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),s(a,{href:"https://github.com/Yufei-Yan"},{default:i(()=>[...e[4]||(e[4]=[t("Yufei-Yan",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),s(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const x=n(d,[["render",b]]);export{T as __pageData,x as default};
